/*
 * ui_font.h - bitmap fonts of the front panel (pure C11).
 *
 * Two fonts, same code page (single byte):
 *   0x20..0x7E  ASCII
 *   0x7F        blank
 *   0x80..0x9F  UI symbols (UI_G_* below), partly drawn for this project, partly from the source fonts
 * Glyph data: `h` bytes per glyph, one byte per row, bit 7 = leftmost pixel (w <= 8).
 * Data and provenance: ui_font_data.c (generated by tools/gen_fonts.py), fonts/README.md.
 */
#pragma once

#include <stdint.h>

typedef struct {
    uint8_t w, h;           /**< cell size in pixels */
    uint8_t first;          /**< first code (0x20) */
    uint8_t count;          /**< number of glyphs (0x80 = codes 0x20..0x9F) */
    const uint8_t *bits;    /**< count * h bytes */
} ui_font_t;

extern const ui_font_t ui_font_8x16b; /**< 8x16 bold: menus, values, port lines, short name */
extern const ui_font_t ui_font_6x8;   /**< 6x8: header/path, hint line, IP line, toasts */

/* UI symbols as string literals (use with string concatenation: "Port 1 " UI_G_OUT). */
#define UI_G_OUT       "\x80" /**< right triangle: output */
#define UI_G_IN        "\x81" /**< left triangle: input */
#define UI_G_DASH      "\x82" /**< en dash: port off */
#define UI_G_REMOTE    "\x83" /**< circular arrow: changed remotely */
#define UI_G_DOWN      "\x84" /**< down arrow: update/download */
#define UI_G_CHECK     "\x85" /**< check mark */
#define UI_G_BKSP      "\x86" /**< backspace (erase left) */
#define UI_G_SPACE     "\x87" /**< visible space (open box) */
#define UI_G_WARN      "\x88" /**< warning triangle with ! */
#define UI_G_LINK      "\x89" /**< link up (up triangle / ethernet) */
#define UI_G_NOLINK    "\x8A" /**< cross: no link */
#define UI_G_LOCK      "\x8B" /**< padlock */
#define UI_G_DOT       "\x8C" /**< filled circle: staged */
#define UI_G_SUB       "\x8D" /**< single right angle quote: submenu */
#define UI_G_ELLIPSIS  "\x8E" /**< horizontal ellipsis */
#define UI_G_MICRO     "\x8F" /**< micro sign */
#define UI_G_RARROW    "\x90" /**< right arrow */
#define UI_G_LARROW    "\x91" /**< left arrow */
#define UI_G_UARROW    "\x92" /**< up arrow */
#define UI_G_LSUB      "\x93" /**< single left angle quote */
#define UI_G_MIDDOT    "\x94" /**< middle dot */
#define UI_G_IDENT     "\x95" /**< sun / identify (circle with rays) */
#define UI_G_BLOCK     "\x96" /**< full block (cursor) */
